function NewsletterForm() {
  const [submitted, setSubmitted] = useState(false)
  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    setSubmitted(true)
  }
  return <form className="newsletter-form" onSubmit={handleSubmit}><label className="sr-only" htmlFor="newsletter-email">Email address</label><input id="newsletter-email" name="email" type="email" placeholder="you@company.com" required disabled={submitted} /><button type="submit" aria-label="Join the NexFlow newsletter" disabled={submitted}>{submitted ? <Check size={16} /> : <ArrowRight size={16} />}</button>{submitted && <span className="newsletter-success" role="status">You’re in. Watch your inbox.</span>}</form>
}

